1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace Drupal\FunctionalTests\Core\Recipe;
6	
7	use Drupal\Component\Serialization\Yaml;
8	use Drupal\Core\Recipe\Recipe;
9	use Drupal\Tests\BrowserTestBase;
10	use Symfony\Component\Process\PhpExecutableFinder;
11	use Symfony\Component\Process\Process;
12	
13	/**
14	 * Contains helper methods for interacting with recipes in functional tests.
15	 */
16	trait RecipeTestTrait {
17	
18	  /**
19	   * Creates a recipe in a temporary directory.
20	   *
21	   * @param string|array<mixed> $data
22	   *   The contents of recipe.yml. If passed as an array, will be encoded to
23	   *   YAML.
24	   * @param string|null $machine_name
25	   *   The machine name for the recipe. Will be used as the directory name.
26	   *
27	   * @return \Drupal\Core\Recipe\Recipe
28	   *   The recipe object.
29	   */
30	  protected function createRecipe(string|array $data, ?string $machine_name = NULL): Recipe {
31	    if (is_array($data)) {
32	      $data = Yaml::encode($data);
33	    }
34	    $recipes_dir = $this->siteDirectory . '/recipes';
35	    if ($machine_name === NULL) {
36	      $dir = uniqid($recipes_dir . '/');
37	    }
38	    else {
39	      $dir = $recipes_dir . '/' . $machine_name;
40	    }
41	    mkdir($dir, recursive: TRUE);
42	    file_put_contents($dir . '/recipe.yml', $data);
43	
44	    return Recipe::createFromDirectory($dir);
45	  }
46	
47	  /**
48	   * Applies a recipe to the site.
49	   *
50	   * @param string $path
51	   *   The path of the recipe to apply. Must be a directory.
52	   * @param int $expected_exit_code
53	   *   The expected exit code of the `drupal recipe` process. Defaults to 0,
54	   *   which indicates that no error occurred.
55	   * @param string[] $options
56	   *   (optional) Additional options to pass to the `drupal recipe` command.
57	   * @param string $command
58	   *   (optional) The name of the command to run. Defaults to `recipe`.
59	   *
60	   * @return \Symfony\Component\Process\Process
61	   *   The `drupal recipe` command process, after having run.
62	   */
63	  protected function applyRecipe(string $path, int $expected_exit_code = 0, array $options = [], string $command = 'recipe'): Process {
64	    assert($this instanceof BrowserTestBase);
65	
66	    $arguments = [
67	      (new PhpExecutableFinder())->find(),
68	      'core/scripts/drupal',
69	      $command,
70	      // Never apply recipes interactively.
71	      '--no-interaction',
72	      ...$options,
73	      $path,
74	    ];
75	    $process = (new Process($arguments))
76	      ->setWorkingDirectory($this->getDrupalRoot())
77	      ->setEnv([
78	        'DRUPAL_DEV_SITE_PATH' => $this->siteDirectory,
79	        // Ensure that the command boots Drupal into a state where it knows it's
80	        // a test site.
81	        // @see drupal_valid_test_ua()
82	        'HTTP_USER_AGENT' => drupal_generate_test_ua($this->databasePrefix),
83	      ])
84	      ->setTimeout(500);
85	
86	    $process->run();
87	    $this->assertSame($expected_exit_code, $process->getExitCode(), $process->getErrorOutput());
88	    // Applying a recipe:
89	    // - creates new checkpoints, hence the "state" service in the test runner
90	    //   is outdated
91	    // - may install modules, which would cause the entire container in the test
92	    //   runner to be outdated.
93	    // Hence the entire environment must be rebuilt for assertions to target the
94	    // actual post-recipe-application result.
95	    // @see \Drupal\Core\Config\Checkpoint\LinearHistory::__construct()
96	    $this->rebuildAll();
97	    return $process;
98	  }
99	
100	  /**
101	   * Alters an existing recipe.
102	   *
103	   * @param string $path
104	   *   The recipe directory path.
105	   * @param callable $alter
106	   *   A function that will receive the decoded contents of recipe.yml as an
107	   *   array. This should returned a modified array to be written to recipe.yml.
108	   */
109	  protected function alterRecipe(string $path, callable $alter): void {
110	    $file = $path . '/recipe.yml';
111	    $this->assertFileExists($file);
112	    $contents = file_get_contents($file);
113	    $contents = Yaml::decode($contents);
114	    $contents = $alter($contents);
115	    file_put_contents($file, Yaml::encode($contents));
116	  }
117	
118	}
